extern "C" unsigned int strlen(const char *);
extern "C" char *strlwr(char *);
extern unsigned char ctype_table[];

#define NULL 0
#define isspace(c) (ctype_table[(signed char)(c)] & 8)

class ini_parser
{
  private:
    enum TokenType {
      NO_TOKEN = 0,
      TOKEN_GROUP,
      TOKEN_STRING,
      TOKEN_EQUALS
    };

    char filename[256];
    char token[256];
    int scan_pos;
    char *line;

    char stored_token;
    char stored_type;
    char stored_num;

    int build_token(char *line, char *the_token);
    int get_token(char **curr_token, int *token_type, int *num_value);
    void despacify_token(char *curr_token);
};

int ini_parser::get_token(char **curr_token, int *token_type, int *num_value)
{
  int ret;
  if (stored_token)
  {
    *curr_token = token;
    *token_type = stored_type;
    *num_value = stored_num;

    stored_token = 0;
    return *token_type;
  }

  token[0] = '\0';
  while( (isspace(line[scan_pos]) && (line[scan_pos] != '\0')) ||
    line[scan_pos] == '\n' || line[scan_pos] == '\r' || line[scan_pos] == ';' )
  {
    if (line[scan_pos] == ';')
    {
      while (line[scan_pos] != '\n' && line[scan_pos] != '\r' && (line[scan_pos] != '\0'))
        ++scan_pos;
    }
    else
      ++scan_pos;
  }
  ret = build_token(&line[scan_pos], token);
  scan_pos += ret;

  if (ret == 0)
  {
    *curr_token = NULL;
    return NO_TOKEN;
  }

  *curr_token = token;
  despacify_token(token);

  if (token[0] == '[')
  {
    strlwr(token);
    *token_type = TOKEN_GROUP;
  }
  else if (token[0] == '=')
    *token_type = TOKEN_EQUALS;
  else if (strlen(token) > 0)
    *token_type = TOKEN_STRING;
  else
    *token_type = NO_TOKEN;
  stored_num = *num_value;
  stored_type = *token_type;

  return *token_type;
}
